/* Event-only work at gate zero leaves base untouched; opening the gate resumes base and both clocks. */
#include "swf_stream_mix_gate_fixture.hpp"
int main()
{
 GateFixture f;FVM_SWFStreamConverter before=f.converter;size_t n=91;for(unsigned i=0;i<7;++i){f.fifo.count=0;assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,0,&n)==FVM_OK && n==2);}assert(!memcmp(&before,&f.converter,sizeof(before)) && f.fifo.total==14);for(unsigned i=0;i<14;++i)assert(f.fifo.samples[i*2]==(i<9?0:-30000) && f.fifo.samples[i*2+1]==f.fifo.samples[i*2]);f.fifo.count=0;assert(fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,0,&n)==FVM_NOT_FOUND && !n);for(unsigned i=0;i<8;++i){f.fifo.count=0;FVM_Result r=fvm_swf_stream_output_pump_mix_until(&f.output,f.mix,1,&n);if(r==FVM_NOT_FOUND)break;assert(r==FVM_OK);}const short expected[]={30000,-25125,11875,-10250,250,-1875,10500,4125,-30000};assert(f.fifo.total==23);for(unsigned i=0;i<9;++i)assert(f.fifo.samples[(i+14)*2]==expected[i]);FVM_SWFStreamOutputInfo info;info.struct_size=sizeof(info);f.fifo.count=0;assert(fvm_swf_stream_output_info(&f.output,&info)==FVM_OK && info.eof && info.submitted_frames==23 && info.played_frames==23);FVM_SWFSoundMixQueueClock clock;clock.struct_size=sizeof(clock);assert(fvm_swf_sound_mix_queue_clock_info(f.mix,&clock)==FVM_OK && clock.submitted_frames==23 && clock.played_frames==23);return 0;
}
